const H = msg.req.headers || {};
const expected = env.get('TOKEN_API_KEY');
if (!expected || H['x-api-key'] !== expected) {
    msg.statusCode = 401;
    msg.payload = { error: 'unauthorized' };
    return [null, msg];
}

const b = msg.req.body || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const E164 = /^\+[1-9]\d{7,14}$/;
const fail = (m) => { msg.statusCode = 400; msg.payload = { error: m }; return [null, msg]; };

if (!UUID.test(b.tenant_id || '')) return fail('tenant_id musí být UUID');
if (!['subscriber', 'client'].includes(b.target_role)) return fail('target_role musí být subscriber nebo client');
if (!E164.test(b.phone || '')) return fail('phone musí být ve formátu E.164, např. +420777123456');

let subscriberId = null;
if (b.target_role === 'client') {
    if (!UUID.test(b.subscriber_id || '')) return fail('client vyžaduje subscriber_id (UUID)');
    subscriberId = b.subscriber_id;
}

const ttl = b.ttl_hours === undefined ? 72 : Number(b.ttl_hours);
if (!Number.isInteger(ttl) || ttl < 1 || ttl > 720) return fail('ttl_hours musí být celé číslo 1–720');

msg.meta = {
    tenantId: b.tenant_id,
    targetRole: b.target_role,
    subscriberId: subscriberId,
    phone: b.phone,
    ttl: ttl
};
return [msg, null];

const token = crypto.randomBytes(24).toString('hex');
const tokenHash = crypto.createHash('sha256').update(token).digest('hex');

msg.token = token; // jen v paměti zprávy, nikdy do DB ani do logu
const m = msg.meta;
msg.params = [m.tenantId, m.subscriberId, m.targetRole, tokenHash, m.ttl];
return msg;

const sid  = env.get('TWILIO_ACCOUNT_SID');
const auth = env.get('TWILIO_AUTH_TOKEN');
const from = env.get('TWILIO_FROM');
const base = env.get('REGISTRATION_URL');
if (!sid || !auth || !from || !base) {
    node.error('Chybí TWILIO_* nebo REGISTRATION_URL v prostředí', msg);
    return null;
}

const text = `Pozvánka do Aetherium Core: ${base}?token=${msg.token}\nPlatí ${msg.meta.ttl} h.`;

msg.method = 'POST';
msg.url = `https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`;
msg.headers = {
    'Authorization': 'Basic ' + Buffer.from(`${sid}:${auth}`).toString('base64'),
    'Content-Type': 'application/x-www-form-urlencoded'
};
msg.payload = new URLSearchParams({ To: msg.meta.phone, From: from, Body: text }).toString();
delete msg.token;   // token už jen v těle SMS
delete msg.params;
return msg;

if (msg.statusCode < 200 || msg.statusCode >= 300) {
    node.warn('Twilio vrátilo HTTP ' + msg.statusCode);
    msg.statusCode = 502;
    msg.headers = {};
    msg.payload = { error: 'sms_failed' };
    return msg;
}
msg.statusCode = 201;
msg.headers = { 'Cache-Control': 'no-store' };
msg.payload = { sent: true, target_role: msg.meta.targetRole, expires_in_hours: msg.meta.ttl };
return msg;

node.warn('Registrační token selhal: ' + (msg.error && msg.error.message));
msg.statusCode = 500;
msg.headers = {};
msg.payload = { error: 'internal_error' };
return msg;
